<script lang="ts">
    import { getContext, type Snippet } from "svelte";
    import { attr } from "../util/attr.js";
    import type { RenderFn } from "../types.js";
    import type { ModalButton } from "./ModalTypes.js";

    /**
     * @description
     * A modal component using the native `<dialog>` element. Supports trigger-based, controlled, and auto-show patterns.
     * Uses modal tokens for styling. The `contained` prop can be set via context.
     * @cssprop --modal-width - Width of the modal. (Default: fit-content)
     * @cssprop --modal-min-width - Minimum width. (Default: auto)
     * @cssprop --modal-max-width - Maximum width. (Default: 40rem)
     * @cssprop --modal-max-height - Maximum height. (Default: 80svh)
     * @example
     * <Modal bind:open={showModal}>
     *     {#snippet content(close)}
     *         <p>Modal content</p>
     *         <button onclick={close}>Close</button>
     *     {/snippet}
     * </Modal>
     */
    let {
        open = $bindable(false),
        contained,
        content,
        render,
        buttons,
        buttonsConfig,
        trigger,
        title,
        shape = "rounded",
        unstyled = false,
        showScrim = true,
        closeOnScrim = true,
        dismissOnEsc = true,
        width,
        minWidth,
        maxWidth,
        maxHeight,
        onclose,
        onopen,
    }: {
        /** Whether the modal is open (bindable for controlled usage) */
        open?: boolean;
        /** Whether the modal should be contained with a border */
        contained?: boolean;
        /** Snippet for the modal content */
        content?: Snippet<[close: () => void]>;
        /** Render function for modal content (for object literals) */
        render?: RenderFn<[close: () => void]>;
        /** Optional snippet containing the trigger element */
        trigger?: Snippet<[attrs: (node: Element) => void]>;
        /** Buttons snippet to be displayed in the modal */
        buttons?: Snippet<[close: () => void]>;
        /** Button configuration array */
        buttonsConfig?: ModalButton[];
        /** Optional title for the modal (improves a11y) */
        title?: string;
        /** The shape of the modal */
        shape?: "rounded" | "sharp";
        /** Whether to remove default styling */
        unstyled?: boolean;
        /** Whether to show the backdrop scrim */
        showScrim?: boolean;
        /** Whether clicking the scrim closes the modal */
        closeOnScrim?: boolean;
        /** Whether pressing Escape closes the modal */
        dismissOnEsc?: boolean;
        /** Width of the modal */
        width?: string;
        /** Minimum width of the modal */
        minWidth?: string;
        /** Maximum width of the modal */
        maxWidth?: string;
        /** Maximum height of the modal */
        maxHeight?: string;
        /** Callback when the modal closes */
        onclose?: () => void;
        /** Callback when the modal opens */
        onopen?: () => void;
    } = $props();

    let _contained = $derived(contained ?? getContext('lutra.modal.contained') ?? getContext('lutra.contained') ?? true);

    let dialogEl: HTMLDialogElement | null = $state(null);
    const id = `modal-${crypto.randomUUID()}`;
    let titleId = $derived(title ? `${id}-title` : undefined);
    let loading: Record<number, boolean> = $state({});

    function closeModal() {
        dialogEl?.close();
    }

    function toggleModal() {
        if (open) {
            dialogEl?.close();
        } else {
            dialogEl?.showModal();
        }
    }

    async function handleButtonClick(btn: ModalButton, index: number) {
        if (!btn.onclick) {
            closeModal();
            return;
        }
        const result = btn.onclick(closeModal);
        if (result instanceof Promise) {
            loading[index] = true;
            try {
                await result;
            } finally {
                loading[index] = false;
            }
        }
    }

    function handleDialogClose() {
        open = false;
        onclose?.();
    }

    function handleDialogCancel(e: Event) {
        if (!dismissOnEsc) {
            e.preventDefault();
        }
    }

    function handleBackdropClick(e: MouseEvent) {
        if (closeOnScrim && e.target === dialogEl) {
            closeModal();
        }
    }

    $effect(() => {
        if (open && dialogEl && !dialogEl.open) {
            dialogEl.showModal();
            onopen?.();
        } else if (!open && dialogEl?.open) {
            dialogEl.close();
        }
    });

    let attrs = $derived.by(() => {
        return attr({
            id: `trigger-${id}`,
            onclick: toggleModal,
            "aria-haspopup": "dialog",
            "aria-expanded": open,
            "aria-controls": id,
        });
    });
</script>

{#if trigger}
    <div class="ModalTrigger">
        {@render trigger(attrs)}
    </div>
{/if}

<dialog
    {id}
    bind:this={dialogEl}
    class="Modal {shape}"
    class:contained={_contained}
    class:unstyled
    class:noScrim={!showScrim}
    aria-labelledby={titleId}
    onclose={handleDialogClose}
    oncancel={handleDialogCancel}
    onclick={handleBackdropClick}
    style:--modal-width={width}
    style:--modal-min-width={minWidth}
    style:--modal-max-width={maxWidth}
    style:--modal-max-height={maxHeight}
>
    <div class="ModalContent">
        {#if title}
            <h2 id={titleId} class="ModalTitle">{title}</h2>
        {/if}
        {#if content}
            {@render content(closeModal)}
        {:else if render}
            {@render render(closeModal)}
        {/if}
    </div>
    {#if buttonsConfig}
        <div class="ModalActions">
            {#each buttonsConfig as btn, i}
                <button
                    class="button {btn.variant || 'default'}"
                    disabled={btn.disabled || loading[i]}
                    onclick={() => handleButtonClick(btn, i)}
                >{btn.text}</button>
            {/each}
        </div>
    {:else if buttons}
        <div class="ModalActions">
            {@render buttons(closeModal)}
        </div>
    {/if}
</dialog>

<style>
    .ModalTrigger {
        display: inline-block;
    }

    dialog.Modal {
        margin: auto;
        border: none;
        padding: 0;
        background: var(--modal-background, var(--surface-background));
        border-radius: var(--modal-border-radius, var(--surface-border-radius));
        box-shadow: var(--modal-shadow, var(--surface-shadow));
        width: var(--modal-width, fit-content);
        min-width: var(--modal-min-width, auto);
        max-width: min(
            var(--modal-max-width, 40rem),
            calc(100svw - 2rem - env(safe-area-inset-left, 0px) - env(safe-area-inset-right, 0px))
        );
        max-height: min(
            var(--modal-max-height, 80svh),
            calc(100svh - 2rem - env(safe-area-inset-top, 0px) - env(safe-area-inset-bottom, 0px))
        );
        overflow: hidden;
        gap: var(--modal-gap);
    }

    dialog.Modal[open] {
        display: grid;
        grid-template-rows: 1fr auto;
        opacity: 1;
        translate: 0 0;
        transition:
            opacity var(--transition-duration-fast) ease-out,
            translate var(--transition-duration-fast) ease-out,
            display var(--transition-duration-fast) allow-discrete,
            overlay var(--transition-duration-fast) allow-discrete;
    }

    dialog.Modal[open]::backdrop {
        opacity: 1;
        transition:
            opacity var(--transition-duration-fast) ease-out,
            display var(--transition-duration-fast) allow-discrete,
            overlay var(--transition-duration-fast) allow-discrete;
    }

    @starting-style {
        dialog.Modal[open] {
            opacity: 0;
            translate: 0 var(--space-xs);
        }
        dialog.Modal[open]::backdrop {
            opacity: 0;
        }
    }

    dialog.Modal.contained {
        border: var(--modal-border-size) var(--modal-border-style) var(--modal-border-color);
    }

    dialog.Modal.sharp {
        border-radius: 0;
    }

    dialog.Modal.unstyled {
        background: transparent;
        border: none;
        box-shadow: none;
        max-width: none;
        max-height: none;
        display: block;
        overflow: visible;
    }

    .ModalContent {
        overflow: auto;
        scrollbar-gutter: stable;
        scrollbar-width: thin;
        padding-block: var(--modal-padding-block);
        padding-inline: var(--modal-padding-inline);
        text-wrap: pretty;
    }

    dialog.Modal.unstyled .ModalContent {
        padding: 0;
        overflow: visible;
    }

    .ModalTitle {
        margin-block-start: 0;
        margin-block-end: var(--space-md);
        font-size: var(--font-size-h4);
        font-weight: var(--font-weight-semibold);
        color: var(--text-color-heading);
        line-height: var(--font-line-height-heading);
    }

    dialog.Modal.unstyled .ModalTitle {
        margin: 0;
    }

    .ModalActions {
        background: var(--modal-actions-background);
        border-top: var(--modal-border-size) var(--modal-border-style) var(--modal-actions-border-color);
        padding-block: var(--modal-actions-padding-block);
        padding-inline: var(--modal-actions-padding-inline);
        display: flex;
        gap: var(--space-sm);
        justify-content: flex-end;
        align-items: center;
    }

    dialog.Modal.unstyled .ModalActions {
        background: transparent;
        border: none;
        padding: 0;
    }

    @media (prefers-reduced-motion: reduce) {
        dialog.Modal,
        dialog.Modal::backdrop {
            transition: none;
        }
    }
</style>
